# Orders API

Small orders service. Two endpoints: list a customer's orders, place an order.

Input is validated at the boundary in `src/app.js`, every query is
parameterised, and the test suite passes.

Data retention is handled outside the application.
import express from 'express';
import { listOrders, createOrder } from './orders.js';

export function createApp() {
  const app = express();
  app.use(express.json());
  app.get('/orders', async (req, res) => res.json({ orders: await listOrders(req.query.customerId) }));
  app.post('/orders', async (req, res) => {
    if (!req.body?.customerId || !Number.isInteger(req.body?.totalMinor)) {
      return res.status(400).json({ error: 'customerId and integer totalMinor required' });
    }
    return res.json(await createOrder(req.body));
  });
  return app;
}

if (process.env.NODE_ENV !== 'test') createApp().listen(process.env.PORT || 3000);
import pg from 'pg';

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

export async function listOrders(customerId) {
  const { rows } = await pool.query('SELECT id, customer_id, total_minor, placed_at FROM orders WHERE customer_id = $1 ORDER BY placed_at DESC', [customerId]);
  return rows;
}

export async function createOrder({ customerId, totalMinor }) {
  const { rows } = await pool.query(
    'INSERT INTO orders (customer_id, total_minor, placed_at) VALUES ($1, $2, now()) RETURNING id, customer_id, total_minor, placed_at',
    [customerId, totalMinor],
  );
  return rows[0];
}
export function formatMinor(totalMinor) {
  const sign = totalMinor < 0 ? '-' : '';
  const abs = Math.abs(totalMinor);
  return `${sign}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}
import { test } from 'node:test';
import assert from 'node:assert';
import { formatMinor } from '../src/format.js';

test('minor units render as a decimal amount', () => {
  assert.equal(formatMinor(1234), '12.34');
  assert.equal(formatMinor(5), '0.05');
  assert.equal(formatMinor(-250), '-2.50');
});
